Stars:
```js
(function makeStars(){
  const n=1600, pos=new Float32Array(n*3), col=new Float32Array(n*3);
  for(let i=0;i<n;i++){
    // random point on sphere shell radius 500-900
    const r = 480+Math.random()*420;
    const t = Math.random()*Math.PI*2, p = Math.acos(2*Math.random()-1);
    pos[i*3]=r*Math.sin(p)*Math.cos(t); pos[i*3+1]=r*Math.cos(p); pos[i*3+2]=r*Math.sin(p)*Math.sin(t);
    const c = 0.7+Math.random()*0.3; // slight tint variation
    col[i*3]=c; col[i*3+1]=c; col[i*3+2]=c*(0.9+Math.random()*0.2);
  }
  const g=new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos,3));
  g.setAttribute('color', new THREE.BufferAttribute(col,3));
  starField = new THREE.Points(g, new THREE.PointsMaterial({size:2.2, vertexColors:true, sizeAttenuation:false, transparent:true, opacity:0.95}));
  scene.add(starField);
})();
```

Colors in r128 vertexColors: pass `vertexColors: true`. Yes.

Particles system:

```js
const MAXP = 2000;
const pGeo = new THREE.BufferGeometry();
const pPos = new Float32Array(MAXP*3), pCol = new Float32Array(MAXP*3);
const pVel = new Float32Array(MAXP*3), pLife = new Float32Array(MAXP), pMax = new Float32Array(MAXP);
pGeo.setAttribute('position', new THREE.BufferAttribute(pPos,3));
pGeo.setAttribute('color', new THREE.BufferAttribute(pCol,3));
const pMat = new THREE.PointsMaterial({size:2.6, vertexColors:true, blending:THREE.AdditiveBlending, depthWrite:false, transparent:true});
const points = new THREE.Points(pGeo, pMat);
points.frustumCulled = false;
scene.add(points);
let pCursor = 0;
function spawnParticles(x,y,z,count,color,speed,life){
  for(let i=0;i<count;i++){
    const j=pCursor; pCursor=(pCursor+1)%MAXP;
    const a=Math.random()*Math.PI*2, b=Math.acos(2*Math.random()-1);
    const s=speed*(0.25+Math.random()*0.75);
    pVel[j*3]=Math.sin(b)*Math.cos(a)*s; pVel[j*3+1]=Math.cos(b)*s*0.6; pVel[j*3+2]=Math.sin(b)*Math.sin(a)*s;
    pPos[j*3]=x; pPos[j*3+1]=y; pPos[j*3+2]=z;
    pLife[j]=pMax[j]=life*(0.6+Math.random()*0.7);
    const c = color; // THREE.Color
    pCol[j*3]=c.r; pCol[j*3+1]=c.g; pCol[j*3+2]=c.b;
  }
}
function updateParticles(dt){
  for(let j=0;j<MAXP;j++){
    if(pLife[j]<=0) continue;
    pLife[j]-=dt;
    if(pLife[j]<=0){ pCol[j*3]=pCol[j*3+1]=pCol[j*3+2]=0; pPos[j*3+1]=-9999; continue; }
    pPos[j*3]+=pVel[j*3]*dt; pPos[j*3+1]+=pVel[j*3+1]*dt; pPos[j*3+2]+=pVel[j*3+2]*dt;
    pVel[j*3]*=0.985; pVel[j*3+1]*=0.985; pVel[j*3+2]*=0.985;
    const f=pLife[j]/pMax[j];
    pCol[j*3]*= 1; // hmm need original color to scale
  }
}
```

Problem: fading by multiplying color each frame compounds and depends on frame rate. Better: store base color per particle and set color = base * f each frame. Add `pBase = new Float32Array(MAXP*3)`. Then in update: `const f = pLife/pMax; col = base*f`. Do that.

