```js
function splitAsteroid(a, impact){
  explode(a.mesh.position..., a.size!==0);
  sfx.explosion(a.size);
  remove a;
  if(a.size < 2){ // 0=large,1=med,2=small
    const n = 2 + (Math.random()<0.5?1:0);
    for(let i=0;i<n;i++){
      const sp = 14 + Math.random()*20 + a.size*6;
      const ang = Math.random()*Math.PI*2;
      spawnAsteroid(a.size+1, pos.x + ..., pos.z + ..., cos*sp + a.vel.x*0.4, sin*sp + a.vel.z*0.4);
    }
  }
  score += [20,50,100][a.size]; updateScoreHUD();
}
```

