```js
function updateShip(dt){
  if(state!=='playing') return;
  if(!player.alive){ player.respawnT-=dt; if(player.respawnT<=0) respawn(); return; }
  player.invuln=Math.max(0,player.invuln-dt);
  player.fireCd=Math.max(0,player.fireCd-dt);
  let turn=0, thrust=false, reverse=false, firing=false;
  if(autopilot){
    aiControl();
    turn=aiState.turn; thrust=aiState.thrust>0; firing=aiState.fire;
  } else {
    turn=((key('ArrowLeft')||key('KeyA'))?1:0)-((key('ArrowRight')||key('KeyD'))?1:0);
    thrust=key('ArrowUp')||key('KeyW');
    reverse=key('ArrowDown')||key('KeyS');
    firing=key('Space');
  }
  player.yaw=wrapAngle(player.yaw+turn*2.8*dt);
  const fwd=forwardVec(player.yaw,tmpV2);
  if(thrust) player.vel.addScaledVector(fwd,95*dt);
  if(reverse) player.vel.addScaledVector(fwd,-60*dt);
  player.vel.multiplyScalar(Math.max(0,1-0.55*dt));
  const sp=player.vel.length();
  if(sp>62) player.vel.multiplyScalar(62/sp);
  player.pos.addScaledVector(player.vel,dt);
  if(wrapPos(player.pos)) wrapSnap=true;
  ship.position.set(player.pos.x, Math.sin(t*2.1)*0.25, player.pos.z);
  ship.rotation.set(0,player.yaw,-turn*0.5);
  ship.visible = player.invuln<=0 || (Math.floor(t*9)%2===0);
  engineGlow.scale.setScalar((thrust?1.15:0.55)+Math.random()*0.12);
  if(firing && player.fireCd<=0) fireBullet();
}
```

