```js
const aiState={turn:0,thrust:1,fire:false};
const aiAvoid=new THREE.Vector3(), aiAim=new THREE.Vector3();
function aiControl(){
  aiAvoid.set(0,0,0);
  let best=null,bestScore=Infinity;
  for(const a of asteroids){
    const dx=a.mesh.position.x-player.pos.x, dz=a.mesh.position.z-player.pos.z;
    const d=Math.hypot(dx,dz)||0.001;
    const closing=-(dx*a.vel.x+dz*a.vel.z)/d;
    const score=d-closing*22;
    if(score<bestScore){bestScore=score;best=a;}
    if(d<85&&closing>1){
      const w=(85-d)/85*2.6;
      aiAvoid.x-=dx/d*w; aiAvoid.z-=dz/d*w;
    }
  }
  if(best){
    const d=Math.hypot(best.mesh.position.x-player.pos.x,best.mesh.position.z-player.pos.z)||0.001;
    const lead=Math.min(d/180,1.1)*0.9;
    aiAim.set(best.mesh.position.x+best.vel.x*lead-player.pos.x,0,best.mesh.position.z+best.vel.z*lead-player.pos.z);
  } else aiAim.set(-player.pos.x,0,-player.pos.z);
  aiAim.add(aiAvoid);
  if(aiAim.lengthSq()<1e-6) aiAim.set(Math.sin(player.yaw),0,Math.cos(player.yaw));
  aiAim.normalize();
  aiAim.x+=Math.sin(t*1.9)*0.05; aiAim.z+=Math.cos(t*1.6)*0.05;
  const targetYaw=Math.atan2(aiAim.x,aiAim.z);
  aiState.turn=clamp(wrapAngle(targetYaw-player.yaw)*3,-1,1);
  aiState.thrust=1;
  aiState.fire=false;
  if(best){
    const dx=best.mesh.position.x-player.pos.x, dz=best.mesh.position.z-player.pos.z;
    const d=Math.hypot(dx,dz);
    const ang=Math.abs(wrapAngle(Math.atan2(dx,dz)-player.yaw));
    aiState.fire = d<360 && ang<0.09;
  }
}
```
