rockGeo with seed:
```js
function rockGeo(radius,detail,seed){
  const g=new THREE.IcosahedronGeometry(radius,detail);
  const p=g.attributes.position, v=new THREE.Vector3();
  for(let i=0;i<p.count;i++){
    v.set(p.getX(i),p.getY(i),p.getZ(i)).normalize();
    const h=Math.sin(v.x*5.7+seed)*Math.cos(v.y*4.9+seed*1.7)*Math.sin(v.z*6.3+seed*0.6)
           +0.5*Math.sin(v.x*11.3+seed*2.1)*Math.cos(v.z*9.7+seed*1.3);
    const s=1+clamp(h,-1,1)*0.3;
    p.setXYZ(i,v.x*radius*s,v.y*radius*s,v.z*radius*s);
  }
  g.computeVertexNormals();
  return g;
}
```
