```js
function updateParticles(dt){
  for(let j=0;j<MAXP;j++){
    if(pLife[j]<=0) continue;
    pLife[j]-=dt;
    if(pLife[j]<=0){ pCol[j*3]=pCol[j*3+1]=pCol[j*3+2]=0; pPos[j*3+1]=-9999; continue; }
    pVel[j*3]*=0.98; pVel[j*3+1]*=0.98; pVel[j*3+2]*=0.98; // frame-rate dependent but ok
    pPos[j*3]+=pVel[j*3]*dt; pPos[j*3+1]+=pVel[j*3+1]*dt; pPos[j*3+2]+=pVel[j*3+2]*dt;
    const f=pLife[j]/pMaxL[j];
    pCol[j*3]=pBase[j*3]*f; pCol[j*3+1]=pBase[j*3+1]*f; pCol[j*3+2]=pBase[j*3+2]*f;
  }
  pGeo.attributes.position.needsUpdate=true;
  pGeo.attributes.color.needsUpdate=true;
}
```
