generic sweep:
```js
function sweep(f0,f1,dur,type,vol){
  if(!actx) return;
  const tt=actx.currentTime, o=actx.createOscillator(), g=actx.createGain();
  o.type=type;
  o.frequency.setValueAtTime(f0,tt);
  o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),tt+dur);
  g.gain.setValueAtTime(vol,tt);
  g.gain.exponentialRampToValueAtTime(0.0001,tt+dur);
  o.connect(g).connect(master);
  o.start(tt); o.stop(tt+dur+0.05);
}
```

sfxExplosion(size):
```js
function sfxExplosion(size){
  if(!actx) return;
  const tt=actx.currentTime;
  const big=size===0;
  const src=actx.createBufferSource(); src.buffer=noiseBuf;
  src.playbackRate.value=big?0.65:size===1?0.9:1.2;
  const f=actx.createBiquadFilter(); f.type='lowpass';
  f.frequency.setValueAtTime(big?950:1500,tt);
  f.frequency.exponentialRampToValueAtTime(50,tt+(big?0.75:0.4));
  const g=actx.createGain();
  g.gain.setValueAtTime(big?0.75:0.4,tt);
  g.gain.exponentialRampToValueAtTime(0.0001,tt+(big?0.8:0.45));
  src.connect(f); f.connect(g); g.connect(master);
  src.start(tt); src.stop(tt+1);
}
```

