    return;
  }
  player.invuln=Math.max(0,player.invuln-dt);
  player.fireCd=Math.max(0,player.fireCd-dt);
  let turn=0,thrust=false,reverse=false,firing=false;
  if(autopilot){
    aiControl();
    turn=aiState.turn;
    thrust=aiState.thrust>0;
    firing=aiState.fire;
  }else{
    turn=((key('ArrowLeft')||key('KeyA'))?1:0)-((key('ArrowRight')||key('KeyD'))?1:0);
    thrust=key('ArrowUp')||key('KeyW');
    reverse=key('ArrowDown')||key('KeyS');
    firing=key('Space');
  }
  player.yaw=wrapAngle(player.yaw+turn*TURN_RATE*dt);
  player.roll+=((-turn*0.55)-player.roll)*Math.min(1,dt*8);
  const fwd=forwardVec(player.yaw,tmpA);
  if(thrust)player.vel.addScaledVector(fwd,ACCEL*dt);
  if(reverse)player.vel.addScaledVector(fwd,-ACCEL*0.6*dt);
  player.vel.multiplyScalar(Math.max(0,1-DRAG*dt));
  const sp=player.vel.length();
  if(sp>MAXSP)player.vel.multiplyScalar(MAXSP/sp);
  player.pos.addScaledVector(player.vel,dt);
  if(wrapPos(player.pos))wrapSnap=true;
  ship.position.set(player.pos.x,Math.sin(t*2.1)*0.25,player.pos.z);
  ship.rotation.set(0,player.yaw,player.roll);
  ship.visible=player.invuln<=0||Math.floor(t*9)%2===0;
  engineGlow.scale.setScalar((thrust?1.2:0.55)+Math.random()*0.12);
  if(firing&&player.fireCd<=0)fireBullet();
}
function updateBullets(dt){
  for(const b of bullets){
    if(!b.active)continue;
    b.life-=dt;
    if(b.life<=0){b.active=false;b.mesh.visible=false;continue;}
    b.mesh.position.addScaledVector(b.vel,dt);
    wrapPos(b.mesh.position);
    for(let i=asteroids.length-1;i>=0;i--){
      const a=asteroids[i],rr=a.r+0.8;
      if(b.mesh.position.distanceToSquared(a.mesh.position)<rr*rr){
        destroyAsteroid(a);
        b.active=false;
        b.mesh.visible=false;
        break;
      }
    }
  }
}
function updateAsteroids(dt){
  for(let i=asteroids.length-1;i>=0;i--){
    const a=asteroids[i],m=a.mesh;
    m.position.x+=a.vel.x*dt;
    m.position.z+=a.vel.z*dt;
    wrapPos(m.position);
    m.rotation.x+=a.rot.x*dt;
    m.rotation.y+=a.rot.y*dt;
    m.rotation.z+=a.rot.z*dt;
    if(state==='playing'&&player.alive&&player.invuln<=0){
      const rr=a.r+2.2;
      if(m.position.distanceToSquared(player.pos)<rr*rr)shipHit();
    }
  }
}
function destroyAsteroid(a){
  const i=asteroids.indexOf(a);
  if(i<0)return;
  asteroids.splice(i,1);
  scene.remove(a.mesh);
  const p=a.mesh.position;
  explode(p.x,p.z,a.size<2);
  spawnParticles(p.x,0,p.z,a.size===0?46:a.size===1?28:14,C_ROCK,20,1.5);
  sfxExplosion(a.size);
  if(a.size<2){
    const n=2+(Math.random()<0.55?1:0);
    for(let k=0;k<n;k++){
      const ang=Math.random()*Math.PI*2,sp=15+Math.random()*20+a.size*9;
      spawnAsteroid(a.size+1,p.x+Math.cos(ang)*a.r*0.6,p.z+Math.sin(ang)*a.r*0.6,Math.cos(ang)*sp+a.vel.x*0.35,Math.sin(ang)*sp+a.vel.z*0.35);
    }
  }
  score+=[20,50,100][a.size];
  hudScore();
}
function shipHit(){
  if(player.invuln>0||!player.alive)return;
  explode(player.pos.x,player.pos.z,true);
  spawnParticles(player.pos.x,0,player.pos.z,60,C_WHITE,38,0.6);
  sfxExplosion(0);
  sfxShipDown();
  player.alive=false;
  ship.visible=false;
  player.respawnT=2.4;
  lives--;
  hudLives();
  if(lives<=0)gameOver();
}
function respawn(){
  player.pos.set(0,0,0);
  player.vel.set(0,0,0);
  player.yaw=0;
  player.roll=0;
  player.alive=true;
  player.invuln=3;
  player.fireCd=0;
  for(const a of asteroids){
    if(a.mesh.position.lengthSq()<5625){
      const ang=Math.random()*Math.PI*2;
      a.mesh.position.set(Math.cos(ang)*ARENA*0.9,0,Math.sin(ang)*ARENA*0.9);
    }
  }
  sfxRespawn();
}
function loadBest(){try{return +localStorage.getItem('asteroidRunBest')||0;}catch(e){return 0;}}
function saveBest(s){try{if(s>(+localStorage.getItem('asteroidRunBest')||0))localStorage.setItem('asteroidRunBest',String(s));}catch(e){}}
function gameOver(){
  state='gameover';
  player.alive=false;
  ship.visible=false;
  goIdleT=0;
  const best=Math.max(score,loadBest());
  saveBest(score);
  elFinal.textContent='SCORE '+pad(score)+'   BEST '+pad(best);
  elOver.style.display='block';
  elCenter.style.display='none';
}
function restart(){
  for(const a of asteroids)scene.remove(a.mesh);
  asteroids.length=0;
  for(const b of bullets){b.active=false;b.mesh.visible=false;}
  score=0;
  hudScore();
  lives=3;
  hudLives();
  elOver.style.display='none';
  elCenter.style.display=everPlayed?'none':'block';
  state='playing';
  player.pos.set(0,0,0);
  player.vel.set(0,0,0);
  player.yaw=0;
  player.roll=0;
  player.alive=true;
  player.invuln=2.5;
  player.fireCd=0;
  spawnT=1.5;
  spawnField();
  wrapSnap=true;
}
function topUpSpawns(dt){
  spawnT-=dt;
  if(spawnT>0)return;
  spawnT=2.2;
  if(asteroids.length<6+Math.min(8,Math.floor(score/700)))spawnEdgeAsteroid();
}
const camPosT=new THREE.Vector3(),camAimT=new THREE.Vector3(),camAim=new THREE.Vector3();
function updateCamera(dt){
  const fwd=forwardVec(player.yaw,tmpB);
  camPosT.copy(player.pos).addScaledVector(fwd,-26);
  camPosT.y+=14;
  camAimT.copy(player.pos).addScaledVector(fwd,12);
  camAimT.y+=1.5;
  if(wrapSnap){
    camera.position.copy(camPosT);
    camAim.copy(camAimT);
    wrapSnap=false;
  }else{
    const k=1-Math.exp(-6*dt);
    camera.position.lerp(camPosT,k);
    camAim.lerp(camAimT,k);
  }
  camera.lookAt(camAim);
}
function updateAuto(){
  const idle=performance.now()-lastInput>3000;
  if(idle===autopilot)return;
  autopilot=idle;
  goIdleT=0;
  elBadge.style.display=autopilot?'block':'none';
  if(!autopilot&&!everPlayed){
    everPlayed=true;
    elCenter.style.display='none';
  }
}
window.addEventListener('keydown',e=>{
  if(e.code==='Space'||e.code.startsWith('Arrow'))e.preventDefault();
  keys.add(e.code);
  lastInput=performance.now();
  ensureAudio();
  if(autopilot){
    autopilot=false;
    goIdleT=0;
    elBadge.style.display='none';
    if(!everPlayed){
      everPlayed=true;
      elCenter.style.display='none';
    }
  }
  if(state==='gameover'&&(e.code==='Enter'||e.code==='Space'))restart();
});
window.addEventListener('keyup',e=>keys.delete(e.code));
window.addEventListener('blur',()=>keys.clear());
window.addEventListener('pointerdown',()=>ensureAudio());
let last=performance.now();
function loop(now){
  requestAnimationFrame(loop);
  const dt=Math.min((now-last)/1000,0.05);
  last=now;
  t+=dt;
  updateAuto();
  if(state==='playing'){
    updateShip(dt);
    updateBullets(dt);
    updateAsteroids(dt);
    topUpSpawns(dt);
  }else{
    updateAsteroids(dt);
    if(autopilot){
      goIdleT+=dt;
      if(goIdleT>2.2)restart();
    }
  }
  updateParticles(dt);
  starField.rotation.y+=dt*0.004;
  updateCamera(dt);
  renderer.render(scene,camera);
}
restart();
requestAnimationFrame(loop);
</script>
</body>
</html>

