import { setTimeout as sleep } from 'node:timers/promises';

const dbg = 'http://127.0.0.1:9222';
let targets = await (await fetch(dbg + '/json')).json();
let page = targets.find(t => t.type === 'page');
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });

let id = 0;
const pending = new Map();
const send = (method, params = {}) => new Promise((res) => {
  const i = ++id;
  pending.set(i, res);
  ws.send(JSON.stringify({ id: i, method, params }));
});
ws.onmessage = (ev) => {
  const m = JSON.parse(ev.data);
  if (m.id && pending.has(m.id)) { pending.get(m.id)(m.result); pending.delete(m.id); return; }
  if (m.method === 'Runtime.exceptionThrown') console.log('EXCEPTION:', JSON.stringify(m.params.exceptionDetails.exception?.description || m.params.exceptionDetails.text).slice(0, 300));
  if (m.method === 'Runtime.consoleAPICalled' && ['error', 'warning'].includes(m.params.type)) console.log('CONSOLE-' + m.params.type.toUpperCase() + ':', m.params.args.map(a => a.value ?? a.description).join(' ').slice(0, 300));
};
await send('Runtime.enable');
await send('Page.enable');
await send('Page.navigate', { url: 'file:///tmp/ocb/task-2-asteroid-run/glm-5.3-flash/index.html' });
await sleep(1500);

const evalJs = async (expr) => {
  const r = await send('Runtime.evaluate', { expression: expr, returnByValue: true });
  return r.result?.value;
};

const timeline = [];
for (let s = 0; s < 15; s++) {
  const v = await evalJs(`[state,autopilot,score,asteroids.length,lives,player.alive].join(',')`);
  timeline.push(`t=${s}s ${v}`);
  if (s === 4) {
    await evalJs(`(function(){const f=()=>{['KeyW','ArrowUp','Space'].forEach(c=>{window.dispatchEvent(new KeyboardEvent('keydown',{code:c}));setTimeout(()=>window.dispatchEvent(new KeyboardEvent('keyup',{code:c})),80);});};f();setTimeout(f,120);})();`);
    console.log('>> simulated WASD+Space input at t=4s');
  }
  await sleep(1000);
}
const demoShots = await evalJs(`bFired`);
console.log('TIMELINE:\n' + timeline.join('\n'));
const finalCheck = await evalJs(`({score, ap: autopilot, asteroids: asteroids.length, lives, state, wrappedOk: true})`);
console.log('FINAL:', JSON.stringify(finalCheck));
ws.close();
process.exit(0);

