const PORT = 9333;
const chrome = spawn('chromium', [
  '--headless=new', '--no-sandbox', '--disable-gpu', '--enable-unsafe-swiftshader',
  '--disable-dev-shm-usage', `--remote-debugging-port=${PORT}`,
  '--window-size=480,320', '--user-data-dir=/tmp/ocb/u' + Date.now(), 'about:blank'
], { stdio: 'ignore' });

const bail = (e) => { console.log('FATAL', e?.message || String(e)); try { chrome.kill('SIGKILL'); } catch {} process.exit(1); };
process.on('exit', () => { try { chrome.kill('SIGKILL'); } catch {} });

let ready = false;
for (let i = 0; i < 20 && !ready; i++) { await sleep(500); try { await (await fetch(`http://127.0.0.1:${PORT}/json/version`)).json(); ready = true; } catch {} }
if (!ready) { console.log('CHROME NOT UP'); process.exit(1); }

const targets = await (await fetch(`http://127.0.0.1:${PORT}/json`)).json();
const page = targets.find(t => t.type === 'page');
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = (e) => rej(new Error('ws fail')); });

let mid = 0;
const pend = new Map();
const send = (method, params = {}) => new Promise((res) => { const i = ++mid; pend.set(i, res); ws.send(JSON.stringify({ id: i, method, params })); });
ws.onmessage = (ev) => {
  const m = JSON.parse(ev.data);
  if (m.id && pend.has(m.id)) { pend.get(m.id)(m.result); pend.delete(m.id); return; }
  if (m.method === 'Runtime.exceptionThrown') console.log('EXCEPTION:', String(m.params.exceptionDetails.exception?.description || m.params.exceptionDetails.text).slice(0, 400));
  if (m.method === 'Runtime.consoleAPICalled' && ['error', 'warning'].includes(m.params.type)) console.log('CONSOLE-' + m.params.type.toUpperCase() + ':', m.params.args.map(a => a.value ?? a.description).join(' ').slice(0, 300));
};
await send('Runtime.enable');
await send('Page.enable');
await send('Page.navigate', { url: 'file:///tmp/ocb/task-2-asteroid-run/glm-5.3-flash/index.html' });
await sleep(1500);
console.log('PAGE LOADED, watching...');

const ev = async (expr) => (await send('Runtime.evaluate', { expression: expr, returnByValue: true }))?.result?.value;

const tl = [];
for (let s = 0; s < 14; s++) {
  const v = await ev(`(() => { try { return [state,autopilot,score,asteroids.length,lives,player.alive].join(','); } catch (e) { return 'ERR ' + e.message; } })()`);
  tl.push(`t=${String(s).padStart(2)}s ${v}`);
  if (s === 4) {
    await ev(`(()=>{['KeyW','ArrowUp','Space'].forEach(c=>{window.dispatchEvent(new KeyboardEvent('keydown',{code:c,bubbles:true}));setTimeout(()=>window.dispatchEvent(new KeyboardEvent('keyup',{code:c,bubbles:true})),120);});setTimeout(()=>{['KeyW','ArrowUp','Space'].forEach(c=>window.dispatchEvent(new KeyboardEvent('keydown',{code:c,bubbles:true})));},200);})();`);
    console.log('>> input injected at t=4s (manual control)');
  }
  await sleep(1000);
}
const badge = await ev(`document.getElementById('badge').style.display`);
const title = await ev(`document.getElementById('center').style.display`);
const hud = await ev(`document.getElementById('score').textContent + ' | ' + document.getElementById('lives').textContent`);
console.log('TIMELINE:\n' + tl.join('\n'));
console.log('badge(display):', badge, '| center(display):', title, '| hud:', hud);
console.log('DONE_OK');
ws.close();
chrome.kill('SIGKILL');
process.exit(0);

