import { spawn } from 'node:child_process';
import { setTimeout as sleep } from 'node:timers/promises';
import fs from 'node:fs';

const PORT = 9333;
const chrome = spawn('chromium', [
  '--headless=new', '--no-sandbox', '--disable-gpu', '--enable-unsafe-swiftshader',
  '--disable-dev-shm-usage', `--remote-debugging-port=${PORT}`,
  '--window-size=480,320', '--user-data-dir=/tmp/ocb/u' + Date.now(), 'about:blank'
], { stdio: 'ignore' });
const clean = () => { try { chrome.kill('SIGKILL'); } catch {} };
process.on('exit', clean);
console.log = ((o) => (...a) => o(a.join(' ')))(console.log);

let excs = 0;
let ready = false;
for (let i = 0; i < 20 && !ready; i++) { await sleep(500); try { await (await fetch(`http://127.0.0.1:${PORT}/json/version`)).json(); ready = true; } catch {} }
if (!ready) { console.log('CHROME NOT UP'); process.exit(1); }

const targets = await (await fetch(`http://127.0.0.1:${PORT}/json`)).json();
const page = targets.find(t => t.type === 'page');
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = () => rej(new Error('ws fail')); });

let mid = 0;
const pend = new Map();
const send = (method, params = {}) => new Promise((res) => { const i = ++mid; pend.set(i, res); ws.send(JSON.stringify({ id: i, method, params })); });
ws.onmessage = (ev) => {
  const m = JSON.parse(ev.data);
  if (m.id && pend.has(m.id)) { pend.get(m.id)(m.result); pend.delete(m.id); return; }
  if (m.method === 'Runtime.exceptionThrown') { excs++; console.log('EXCEPTION: ' + String(m.params.exceptionDetails.exception?.description || m.params.exceptionDetails.text).slice(0, 400)); }
  if (m.method === 'Runtime.consoleAPICalled' && ['error', 'warning'].includes(m.params.type)) console.log('CONSOLE-' + m.params.type.toUpperCase() + ': ' + m.params.args.map(a => a.value ?? a.description).join(' ').slice(0, 300));
};
await send('Runtime.enable');
await send('Page.enable');
await send('Page.navigate', { url: 'file:///tmp/ocb/task-2-asteroid-run/glm-5.3-flash/test.html' });
await sleep(2500);

const ev = async (expr) => (await send('Runtime.evaluate', { expression: expr, returnByValue: true }))?.result?.value;
const probe = async (tag) => console.log(tag, await ev(`JSON.stringify({
  three: typeof THREE,
  gameFn: typeof window.updateAuto,
  badge: document.getElementById('badge').style.display,
  center: document.getElementById('center').style.display,
  over: document.getElementById('gameover').style.display,
  score: document.getElementById('score').textContent,
  lives: document.getElementById('lives').textContent
})`));
const tap = () => ev(`(()=>{const d=new KeyboardEvent('keydown',{code:'ArrowLeft',bubbles:true});const u=new KeyboardEvent('keyup',{code:'ArrowLeft',bubbles:true});window.dispatchEvent(d);setTimeout(()=>window.dispatchEvent(u),150);})();`);

await probe('P1(auto@boot)');
await tap();
await sleep(400);
await probe('P2(after tap -> manual)');
await sleep(4000);
await probe('P3(idle 3s -> AI again)');
const shots = [];
for (let s = 0; s < 10; s++) {
  shots.push(await ev(`document.getElementById('score').textContent`));
  await sleep(1000);
}
console.log('SCORE TRACE (AI playing):', shots.join(' '));
console.log('keydown count:', await ev(`String(window.__k)`));
const shot = await send('Page.captureScreenshot', { format: 'png' });
fs.writeFileSync('shot_final.png', Buffer.from(shot.data, 'base64'));
console.log('EXCEPTIONS_TOTAL:', excs);
console.log('DONE_OK');
ws.close();
clean();
process.exit(0);

